#GENERATED BY FORWARD
TRDPB001_1=DECLARE SETTLEMENT_QUEUE FOR SELECT STQ_ID,STQ_TRADE_DATA FROM TBTRDSTQ WHERE STQ_CURRENCY=? ORDER BY STQ_CURRENCY ASC, STQ_ID ASC
TRDPB001_2=OPEN SETTLEMENT_QUEUE 
TRDPB001_3=INSERT INTO TBTRDLOG VALUES (?,?,?,?)
TRDPB001_4=UPDATE TBTRDLOG SET LOG_END_TS=? WHERE LOG_TRANSACTION=? AND LOG_CURRENCY=?
TRDPB001_5=FETCH NEXT SETTLEMENT_QUEUE
TRDPB001_6=DELETE FROM TBTRDSTQ WHERE STQ_CURRENCY=? AND STQ_ID=?
TRDPB001_7=UPDATE TBTRDORD SET ORD_STATUS=? WHERE ORD_CURRENCY=? AND ORD_TRADING_XCHNG=? AND ORD_TRADEID=? AND ORD_FIGI=? AND ORD_BUY_SELL_IND=?
TRDPB001_8=SELECT SUM_CUSTOMER_ID, SUM_OVERDUE, SUM_REJECTED, SUM_SETTLED, SUM_CURRENCY, SUM_OPEN_BALANCE, SUM_TOTAL_DEBIT, SUM_TOTAL_CREDIT, SUM_CLOSE_BALANCE FROM TBTRDSUM WHERE SUM_CUSTOMER_ID=?
TRDPB001_9=SELECT MAC_BALANCE FROM TBTRDMAC WHERE MAC_CURRENCY=? AND MAC_NUMBER=?    
TRDPB001_10=INSERT INTO TBTRDSUM VALUES (?,?,?,?,?,?,?,?,?)
TRDPB001_11=UPDATE TBTRDSUM SET SUM_OVERDUE=? ,SUM_REJECTED=? ,SUM_SETTLED=? ,SUM_CURRENCY=? ,SUM_OPEN_BALANCE=? ,SUM_TOTAL_DEBIT=? ,SUM_TOTAL_CREDIT=? ,SUM_CLOSE_BALANCE=? WHERE SUM_CUSTOMER_ID=?
